export interface DoVuiQuestion {
  topic: DoVuiTopicId;
  category: string;
  difficulty: 'hard' | 'extreme';
  q: string;
  options: [string, string, string, string];
  correct: 0 | 1 | 2 | 3;
  explain: string;
}

export interface DoVuiView {
  type: 'do_vui';
  index: number;
  total: number;
  phase: DoVuiPhase;
  phaseEndsAt: number | null;
  phaseSeconds: number;
  category: string;
  selectedTopic?: DoVuiTopic;
  difficulty?: 'hard' | 'extreme';
  question: string;
  options: [string, string, string, string];
  doublePoints: boolean;
  order: string[];
  names: Record<string, string>;
  scores: Record<string, number>;
  streaks: Record<string, number>;
  answeredIds: string[];
  myAnswer: number | null;
  /** Chỉ gửi ở phase === 'reveal' (chống gian lận soi đáp án khi đang trả lời) */
  correctIndex?: number | null;
  explain?: string | null;
  picks?: Record<string, number> | null;
}

type QTuple = ['hard' | 'extreme', string, string, string, string, string, 0 | 1 | 2 | 3, string];

function qs(topic: DoVuiTopicId, category: string, rows: QTuple[]): DoVuiQuestion[] {
  return rows.map(([difficulty, q, a, b, c, d, correct, explain]) => ({
    topic,
    category,
    difficulty,
    q,
    options: [a, b, c, d],
    correct,
    explain,
  }));
}

