/**
 * Trả về danh sách câu hỏi theo chuyên đề (`'all'` hoặc bỏ trống sẽ lấy toàn bộ ngân hàng câu hỏi).
 */
export function questionsForTopic(topic?: DoVuiTopic): DoVuiQuestion[] {
  if (!topic || topic === 'all') return [...DO_VUI_QUESTIONS];
  const filtered = DO_VUI_QUESTIONS.filter((q) => q.topic === topic);
  return filtered.length > 0 ? filtered : [...DO_VUI_QUESTIONS];
}
